@ActiveProfiles("test") @SpringBootTest(properties={"app.security.supabase.mode=HMAC","app.security.supabase.algorithm=HS256","app.security.supabase.issuer=https://auth.example.test/auth/v1","app.security.supabase.hmac-secret=test-only-hmac-key-with-at-least-32-bytes","app.security.supabase.audiences=authenticated","app.security.supabase.accepted-token-roles=authenticated"}) @AutoConfigureMockMvc
class InvitationConcurrencyIntegrationTest extends com.gerenciadorrural.infrastructure.database.SpringPostgresTestSupport {
 private static final String SECRET="test-only-hmac-key-with-at-least-32-bytes",ISSUER="https://auth.example.test/auth/v1"; @Autowired MockMvc mvc;
 @BeforeEach void clean()throws Exception{PostgresTestEnvironment.clearUsers();}
 @Test void sameTokenAcceptanceHasOneEffectAcrossFiveRealHttpRaces()throws Exception{for(int i=0;i<5;i++){UUID org=UUID.randomUUID(),user=UUID.randomUUID(),inv=UUID.randomUUID();String raw="token-"+UUID.randomUUID();seed(org,user,inv,hash(raw));List<Integer> status=race(raw,token(user,"invitee@example.test"));assertThat(status).contains(204);assertThat(count("organization_memberships","tenant_id",org)).isEqualTo(1);assertThat(count("platform_admin_events","organization_id",org)).isEqualTo(1);assertThat(text(inv,"organization_invitations","status")).isEqualTo("ACCEPTED");}}
 @Test void concurrentOwnerRevocationsNeverLeaveAnOrganizationWithoutOwner()throws Exception{for(int i=0;i<5;i++){UUID o=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID(),ma=UUID.randomUUID(),mb=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+a+"','a"+i+"@x.test','ACTIVE'),('"+b+"','b"+i+"@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+ma+"','"+o+"','"+a+"','OWNER','ACTIVE','ALL_FARMS'),('"+mb+"','"+o+"','"+b+"','OWNER','ACTIVE','ALL_FARMS')");}List<Integer> r=raceDelete(o,ma,mb,token(a,"a"+i+"@x.test"),token(b,"b"+i+"@x.test"));assertThat(r).containsAnyOf(204,409);assertThat(owners(o)).isGreaterThanOrEqualTo(1);}}
 @Test void revocationAndRolePatchHaveExactlyOneWinnerAcrossFiveRaces()throws Exception{for(int i=0;i<5;i++){UUID o=UUID.randomUUID(),a=UUID.randomUUID(),u=UUID.randomUUID(),ma=UUID.randomUUID(),m=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+a+"','owner"+i+"@x.test','ACTIVE'),('"+u+"','member"+i+"@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+ma+"','"+o+"','"+a+"','OWNER','ACTIVE','ALL_FARMS'),('"+m+"','"+o+"','"+u+"','MANAGER','ACTIVE','ALL_FARMS')");}List<Integer> r=racePatchDelete(o,m,token(a,"owner"+i+"@x.test"));assertThat(r).containsAnyOf(200,204);assertThat(version(m)).isEqualTo(1);assertThat(events(o)).isEqualTo(1);}}
 @Test void scopePatchAndRevocationHaveExactlyOneWinnerAcrossFiveRaces()throws Exception{for(int i=0;i<5;i++){UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),user=UUID.randomUUID(),ownerMembership=UUID.randomUUID(),membership=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID();try(Connection connection=PostgresTestEnvironment.adminConnection();Statement statement=connection.createStatement()){statement.execute("insert into app.users(id,email,status) values('"+owner+"','scope-owner"+i+"@x.test','ACTIVE'),('"+user+"','scope-member"+i+"@x.test','ACTIVE')");statement.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");statement.execute("insert into app.farms(id,tenant_id,name,status) values('"+a+"','"+o+"','A','ACTIVE'),('"+b+"','"+o+"','B','ACTIVE'),('"+c+"','"+o+"','C','ACTIVE')");statement.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+ownerMembership+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS'),('"+membership+"','"+o+"','"+user+"','VIEWER','ACTIVE','SELECTED_FARMS')");statement.execute("insert into app.membership_farm_scopes(tenant_id,membership_id,farm_id) values('"+o+"','"+membership+"','"+a+"'),('"+o+"','"+membership+"','"+b+"')");}List<Integer> statuses=raceScopePatchDelete(o,membership,c,token(owner,"scope-owner"+i+"@x.test"));assertThat(statuses).containsAnyOf(200,204);assertThat(statuses).doesNotContain(500);assertThat(version(membership)).isEqualTo(1);assertThat(events(o)).isEqualTo(1);assertThat(memberStatus(membership)).isIn("ACTIVE","REVOKED");if("REVOKED".equals(memberStatus(membership)))assertThat(scopes(o,membership)).containsExactlyInAnyOrder(a,b);else assertThat(scopes(o,membership)).containsExactly(c);}}
 @Test void acceptAndRevocationProduceOneTerminalInvitationEffectAcrossFiveRaces()throws Exception{for(int i=0;i<5;i++){UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),invitee=UUID.randomUUID(),mo=UUID.randomUUID(),inv=UUID.randomUUID();String raw="race-"+UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+owner+"','owner"+i+"@x.test','ACTIVE'),('"+invitee+"','invitee"+i+"@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+mo+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS')");s.execute("insert into app.organization_invitations(id,organization_id,invited_email,normalized_email,role_key,farm_scope_mode,status,token_hash,invited_by_user_id,expires_at) values('"+inv+"','"+o+"','invitee"+i+"@x.test','invitee"+i+"@x.test','VIEWER','ALL_FARMS','PENDING','"+hash(raw)+"','"+owner+"',current_timestamp+interval '1 day')");}List<Integer> r=raceAcceptRevoke(o,inv,raw,token(owner,"owner"+i+"@x.test"),token(invitee,"invitee"+i+"@x.test"));String status=text(inv,"organization_invitations","status");assertThat(status).isIn("ACCEPTED","REVOKED");assertThat(count("organization_memberships","tenant_id",o)).isEqualTo("ACCEPTED".equals(status)?2:1);assertThat(events(o)).isEqualTo(1);}}
 @Test void revokedMembershipIsRejectedImmediatelyWithTheSameJwt()throws Exception{UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),user=UUID.randomUUID(),mo=UUID.randomUUID(),m=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+owner+"','owner@x.test','ACTIVE'),('"+user+"','user@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+mo+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS'),('"+m+"','"+o+"','"+user+"','VIEWER','ACTIVE','ALL_FARMS')");}String u=token(user,"user@x.test"),a=token(owner,"owner@x.test");assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/organizations/"+o).header(HttpHeaders.AUTHORIZATION,"Bearer "+u)).andReturn().getResponse().getStatus()).isEqualTo(200);assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/v1/organizations/"+o+"/members/"+m).queryParam("expectedVersion","0").header(HttpHeaders.AUTHORIZATION,"Bearer "+a)).andReturn().getResponse().getStatus()).isEqualTo(204);assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/organizations/"+o).header(HttpHeaders.AUTHORIZATION,"Bearer "+u)).andReturn().getResponse().getStatus()).isEqualTo(404);}
 @Test void removedFarmScopeIsRejectedImmediatelyWithTheSameJwt()throws Exception{UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),user=UUID.randomUUID(),mo=UUID.randomUUID(),m=UUID.randomUUID(),fa=UUID.randomUUID(),fb=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+owner+"','owner-s@x.test','ACTIVE'),('"+user+"','user-s@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.farms(id,tenant_id,name,status) values('"+fa+"','"+o+"','A','ACTIVE'),('"+fb+"','"+o+"','B','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+mo+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS'),('"+m+"','"+o+"','"+user+"','VIEWER','ACTIVE','SELECTED_FARMS')");s.execute("insert into app.membership_farm_scopes(tenant_id,membership_id,farm_id) values('"+o+"','"+m+"','"+fa+"')");}String u=token(user,"user-s@x.test"),a=token(owner,"owner-s@x.test");assertThat(context(o,fa,u)).isEqualTo(200);assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+m).header(HttpHeaders.AUTHORIZATION,"Bearer "+a).contentType(MediaType.APPLICATION_JSON).content("{\"farmScopeMode\":\"SELECTED_FARMS\",\"farmIds\":[\""+fb+"\"],\"expectedVersion\":0}")).andReturn().getResponse().getStatus()).isEqualTo(200);assertThat(context(o,fa,u)).isEqualTo(404);}
 @Test void downgradedAdminLosesFarmAdministrationWithTheSameJwt()throws Exception{UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),admin=UUID.randomUUID(),mo=UUID.randomUUID(),m=UUID.randomUUID();try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+owner+"','owner-r@x.test','ACTIVE'),('"+admin+"','admin-r@x.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+mo+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS'),('"+m+"','"+o+"','"+admin+"','ADMIN','ACTIVE','ALL_FARMS')");}String a=token(admin,"admin-r@x.test"),own=token(owner,"owner-r@x.test");assertThat(createFarm(o,a)).isEqualTo(201);assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+m).header(HttpHeaders.AUTHORIZATION,"Bearer "+own).contentType(MediaType.APPLICATION_JSON).content("{\"role\":\"VIEWER\",\"expectedVersion\":0}")).andReturn().getResponse().getStatus()).isEqualTo(200);assertThat(createFarm(o,a)).isEqualTo(403);}
 @Test void auditFailureRollsBackFarmCreationAndRetrySucceeds()throws Exception{UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),membership=UUID.randomUUID(),farm=UUID.randomUUID();try(Connection connection=PostgresTestEnvironment.adminConnection();Statement statement=connection.createStatement()){statement.execute("insert into app.users(id,email,status) values('"+owner+"','atomic-farm@x.test','ACTIVE')");statement.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");statement.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+membership+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS')");}installEventFault();try{var response=mvc.perform(post("/api/v1/organizations/"+o+"/farms").header(HttpHeaders.AUTHORIZATION,"Bearer "+token(owner,"atomic-farm@x.test")).contentType(MediaType.APPLICATION_JSON).content("{\"id\":\""+farm+"\",\"name\":\"Falha\"}")).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(503);assertThat(response.getContentAsString()).doesNotContain("phase08", "trigger", "SQL", "app.");assertThat(count("farms","id",farm)).isZero();assertThat(events(o)).isZero();}finally{dropEventFault();}assertThat(createFarm(o,token(owner,"atomic-farm@x.test"))).isEqualTo(201);assertThat(count("farms","tenant_id",o)).isOne();assertThat(events(o)).isOne();}
 @Test void auditFailureRollsBackScopeMutationAndRetrySucceeds()throws Exception{UUID o=UUID.randomUUID(),owner=UUID.randomUUID(),user=UUID.randomUUID(),ownerMembership=UUID.randomUUID(),membership=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();try(Connection connection=PostgresTestEnvironment.adminConnection();Statement statement=connection.createStatement()){statement.execute("insert into app.users(id,email,status) values('"+owner+"','atomic-scope-owner@x.test','ACTIVE'),('"+user+"','atomic-scope-member@x.test','ACTIVE')");statement.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");statement.execute("insert into app.farms(id,tenant_id,name,status) values('"+a+"','"+o+"','A','ACTIVE'),('"+b+"','"+o+"','B','ACTIVE')");statement.execute("insert into app.organization_memberships(id,tenant_id,user_id,role_key,status,farm_scope_mode) values('"+ownerMembership+"','"+o+"','"+owner+"','OWNER','ACTIVE','ALL_FARMS'),('"+membership+"','"+o+"','"+user+"','VIEWER','ACTIVE','SELECTED_FARMS')");statement.execute("insert into app.membership_farm_scopes(tenant_id,membership_id,farm_id) values('"+o+"','"+membership+"','"+a+"')");}String jwt=token(owner,"atomic-scope-owner@x.test");installEventFault();try{var response=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+membership).header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt).contentType(MediaType.APPLICATION_JSON).content("{\"farmScopeMode\":\"SELECTED_FARMS\",\"farmIds\":[\""+b+"\"],\"expectedVersion\":0}")).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(503);assertThat(version(membership)).isZero();assertThat(scopes(o,membership)).containsExactly(a);assertThat(events(o)).isZero();}finally{dropEventFault();}assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+membership).header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt).contentType(MediaType.APPLICATION_JSON).content("{\"farmScopeMode\":\"SELECTED_FARMS\",\"farmIds\":[\""+b+"\"],\"expectedVersion\":0}")).andReturn().getResponse().getStatus()).isEqualTo(200);assertThat(version(membership)).isEqualTo(1);assertThat(scopes(o,membership)).containsExactly(b);assertThat(events(o)).isOne();}
 private void seed(UUID o,UUID u,UUID i,String h)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("insert into app.users(id,email,status) values('"+u+"','invitee@example.test','ACTIVE')");s.execute("insert into app.organizations(id,name,status) values('"+o+"','O','ACTIVE')");s.execute("insert into app.organization_invitations(id,organization_id,invited_email,normalized_email,role_key,farm_scope_mode,status,token_hash,invited_by_user_id,expires_at) values('"+i+"','"+o+"','invitee@example.test','invitee@example.test','VIEWER','ALL_FARMS','PENDING','"+h+"','"+u+"',current_timestamp+interval '1 day')");}}
 private List<Integer> race(String raw,String jwt)throws Exception{ExecutorService e=Executors.newFixedThreadPool(2);CyclicBarrier b=new CyclicBarrier(2);try{Future<Integer>a=e.submit(()->call(b,raw,jwt)),d=e.submit(()->call(b,raw,jwt));return List.of(a.get(20,TimeUnit.SECONDS),d.get(20,TimeUnit.SECONDS));}finally{e.shutdownNow();assertThat(e.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}}
 private int call(CyclicBarrier b,String raw,String jwt)throws Exception{b.await(10,TimeUnit.SECONDS);return mvc.perform(post("/api/v1/invitations/"+raw+"/accept").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt)).andReturn().getResponse().getStatus();}
 private List<Integer> raceDelete(UUID o,UUID a,UUID b,String ta,String tb)throws Exception{ExecutorService e=Executors.newFixedThreadPool(2);CyclicBarrier gate=new CyclicBarrier(2);try{Future<Integer>x=e.submit(()->{gate.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/v1/organizations/"+o+"/members/"+b).queryParam("expectedVersion","0").header(HttpHeaders.AUTHORIZATION,"Bearer "+ta)).andReturn().getResponse().getStatus();}),y=e.submit(()->{gate.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/v1/organizations/"+o+"/members/"+a).queryParam("expectedVersion","0").header(HttpHeaders.AUTHORIZATION,"Bearer "+tb)).andReturn().getResponse().getStatus();});return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}finally{e.shutdownNow();assertThat(e.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}}
 private List<Integer> racePatchDelete(UUID o,UUID m,String jwt)throws Exception{ExecutorService e=Executors.newFixedThreadPool(2);CyclicBarrier g=new CyclicBarrier(2);try{Future<Integer>x=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+m).header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt).contentType(MediaType.APPLICATION_JSON).content("{\"role\":\"OPERATOR\",\"expectedVersion\":0}")).andReturn().getResponse().getStatus();}),y=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/v1/organizations/"+o+"/members/"+m).queryParam("expectedVersion","0").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt)).andReturn().getResponse().getStatus();});return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}finally{e.shutdownNow();assertThat(e.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}}
 private List<Integer> raceScopePatchDelete(UUID o,UUID m,UUID farm,String jwt)throws Exception{ExecutorService e=Executors.newFixedThreadPool(2);CyclicBarrier g=new CyclicBarrier(2);try{Future<Integer>x=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch("/api/v1/organizations/"+o+"/members/"+m).header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt).contentType(MediaType.APPLICATION_JSON).content("{\"farmScopeMode\":\"SELECTED_FARMS\",\"farmIds\":[\""+farm+"\"],\"expectedVersion\":0}")).andReturn().getResponse().getStatus();}),y=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete("/api/v1/organizations/"+o+"/members/"+m).queryParam("expectedVersion","0").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt)).andReturn().getResponse().getStatus();});return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}finally{e.shutdownNow();assertThat(e.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}}
 private List<Integer> raceAcceptRevoke(UUID o,UUID i,String raw,String owner,String invitee)throws Exception{ExecutorService e=Executors.newFixedThreadPool(2);CyclicBarrier g=new CyclicBarrier(2);try{Future<Integer>x=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(post("/api/v1/invitations/"+raw+"/accept").header(HttpHeaders.AUTHORIZATION,"Bearer "+invitee)).andReturn().getResponse().getStatus();}),y=e.submit(()->{g.await(10,TimeUnit.SECONDS);return mvc.perform(post("/api/v1/organizations/"+o+"/invitations/"+i+"/revocation").header(HttpHeaders.AUTHORIZATION,"Bearer "+owner)).andReturn().getResponse().getStatus();});return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}finally{e.shutdownNow();assertThat(e.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}}
 private static String hash(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));} private int count(String table,String col,Object value)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();PreparedStatement p=c.prepareStatement("select count(*) from app."+table+" where "+col+"=?")){p.setObject(1,value);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}} private String text(UUID id,String table,String col)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select "+col+" from app."+table+" where id='"+id+"'")){r.next();return r.getString(1);}}
 private void installEventFault()throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("create function app.phase08_event_fault() returns trigger language plpgsql as 'begin raise exception ''phase08 injected persistence failure''; end' ");s.execute("create trigger phase08_event_fault before insert on app.platform_admin_events for each row execute function app.phase08_event_fault()");}} private void dropEventFault()throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement()){s.execute("drop trigger if exists phase08_event_fault on app.platform_admin_events");s.execute("drop function if exists app.phase08_event_fault()");}}
 private int owners(UUID o)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select count(*) from app.organization_memberships where tenant_id='"+o+"' and status='ACTIVE' and role_key='OWNER'")){r.next();return r.getInt(1);}}
 private int context(UUID o,UUID f,String jwt)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/context").header("X-Organization-Id",o).header("X-Farm-Id",f).header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt)).andReturn().getResponse().getStatus();}
 private int createFarm(UUID o,String jwt)throws Exception{return mvc.perform(post("/api/v1/organizations/"+o+"/farms").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt).contentType(MediaType.APPLICATION_JSON).content("{\"id\":\""+UUID.randomUUID()+"\",\"name\":\"F\"}")).andReturn().getResponse().getStatus();}
 private int version(UUID id)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select version from app.organization_memberships where id='"+id+"'")){r.next();return r.getInt(1);}} private int events(UUID o)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select count(*) from app.platform_admin_events where organization_id='"+o+"'")){r.next();return r.getInt(1);}}
 private String memberStatus(UUID id)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("select status from app.organization_memberships where id='"+id+"'")){r.next();return r.getString(1);}} private List<UUID> scopes(UUID o,UUID m)throws Exception{try(Connection c=PostgresTestEnvironment.adminConnection();PreparedStatement p=c.prepareStatement("select farm_id from app.membership_farm_scopes where tenant_id=? and membership_id=? order by farm_id")){p.setObject(1,o);p.setObject(2,m);try(ResultSet r=p.executeQuery()){List<UUID> result=new ArrayList<>();while(r.next())result.add(r.getObject(1,UUID.class));return result;}}}
 private static String token(UUID user,String email)throws Exception{JWTClaimsSet c=new JWTClaimsSet.Builder().issuer(ISSUER).audience("authenticated").subject(user.toString()).claim("role","authenticated").claim("email",email).issueTime(new java.util.Date()).expirationTime(java.util.Date.from(Instant.now().plusSeconds(300))).build();SignedJWT j=new SignedJWT(new JWSHeader(JWSAlgorithm.HS256),c);j.sign(new MACSigner(SECRET.getBytes()));return j.serialize();}
}
